const fs = require("fs");
const formidable = require("formidable");

const OPENAI_API_KEY = process.env.OPENAI_API_KEY;

module.exports = async function handler(req, res) {
  // Only POST requests are allowed
    if (req.method !== "POST") {
        return res.status(405).json({
              error: "Method not allowed"
                  });
                    }

                      // Check API key
                        if (!OPENAI_API_KEY) {
                            return res.status(500).json({
                                  error: "OPENAI_API_KEY is not configured."
                                      });
                                        }

                                          try {
                                              // Parse uploaded clothing image
                                                  const form = formidable({
                                                        multiples: false,
                                                              maxFileSize: 12 * 1024 * 1024,
                                                                    keepExtensions: true
                                                                        });

                                                                            const [fields, files] = await new Promise((resolve, reject) => {
                                                                                  form.parse(req, (err, fields, files) => {
                                                                                          if (err) {
                                                                                                    reject(err);
                                                                                                              return;
                                                                                                                      }

                                                                                                                              resolve([fields, files]);
                                                                                                                                    });
                                                                                                                                        });

                                                                                                                                            // Find uploaded clothing image
                                                                                                                                                let clothingFile =
                                                                                                                                                      files.image ||
                                                                                                                                                            files.clothing ||
                                                                                                                                                                  files.file ||
                                                                                                                                                                        files.photo;

                                                                                                                                                                            // Formidable can sometimes return an array
                                                                                                                                                                                if (Array.isArray(clothingFile)) {
                                                                                                                                                                                      clothingFile = clothingFile[0];
                                                                                                                                                                                          }

                                                                                                                                                                                              if (!clothingFile) {
                                                                                                                                                                                                    return res.status(400).json({
                                                                                                                                                                                                            error: "No clothing image was uploaded."
                                                                                                                                                                                                                  });
                                                                                                                                                                                                                      }

                                                                                                                                                                                                                          // Get temporary file path
                                                                                                                                                                                                                              const imagePath =
                                                                                                                                                                                                                                    clothingFile.filepath ||
                                                                                                                                                                                                                                          clothingFile.path;

                                                                                                                                                                                                                                              if (!imagePath || !fs.existsSync(imagePath)) {
                                                                                                                                                                                                                                                    return res.status(400).json({
                                                                                                                                                                                                                                                            error: "Uploaded clothing image could not be found."
                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                          // Read uploaded image
                                                                                                                                                                                                                                                                              const imageBuffer = fs.readFileSync(imagePath);

                                                                                                                                                                                                                                                                                  // Determine image type
                                                                                                                                                                                                                                                                                      const mimeType =
                                                                                                                                                                                                                                                                                            clothingFile.mimetype ||
                                                                                                                                                                                                                                                                                                  clothingFile.type ||
                                                                                                                                                                                                                                                                                                        "image/jpeg";

                                                                                                                                                                                                                                                                                                            const originalName =
                                                                                                                                                                                                                                                                                                                  clothingFile.originalFilename ||
                                                                                                                                                                                                                                                                                                                        clothingFile.name ||
                                                                                                                                                                                                                                                                                                                              "clothing.jpg";

                                                                                                                                                                                                                                                                                                                                  /*
                                                                                                                                                                                                                                                                                                                                       * IMPORTANT:
                                                                                                                                                                                                                                                                                                                                            *
                                                                                                                                                                                                                                                                                                                                                 * This prompt deliberately tells the image model that the
                                                                                                                                                                                                                                                                                                                                                      * uploaded garment is the source of truth.
                                                                                                                                                                                                                                                                                                                                                           *
                                                                                                                                                                                                                                                                                                                                                                * The model should create the fashion photograph around
                                                                                                                                                                                                                                                                                                                                                                     * the clothing rather than redesigning the clothing.
                                                                                                                                                                                                                                                                                                                                                                          */
                                                                                                                                                                                                                                                                                                                                                                              const prompt = `
                                                                                                                                                                                                                                                                                                                                                                              Create a professional photorealistic fashion photograph using the uploaded clothing image as the PRIMARY AND EXACT CLOTHING REFERENCE.

                                                                                                                                                                                                                                                                                                                                                                              CLOTHING PRESERVATION IS THE HIGHEST PRIORITY.

                                                                                                                                                                                                                                                                                                                                                                              The person, pose, hairstyle, body, lighting, location and background may be newly created, but the uploaded garment itself must remain as faithful to the reference as possible.

                                                                                                                                                                                                                                                                                                                                                                              STRICTLY PRESERVE:

                                                                                                                                                                                                                                                                                                                                                                              1. Exact garment silhouette and overall shape.
                                                                                                                                                                                                                                                                                                                                                                              2. Exact garment color and color placement.
                                                                                                                                                                                                                                                                                                                                                                              3. Exact neckline shape.
                                                                                                                                                                                                                                                                                                                                                                              4. Exact sleeve length, sleeve shape and sleeve construction.
                                                                                                                                                                                                                                                                                                                                                                              5. Exact cuffs, collar, seams and visible stitching.
                                                                                                                                                                                                                                                                                                                                                                              6. Exact fabric appearance and texture.
                                                                                                                                                                                                                                                                                                                                                                              7. Exact graphic artwork, illustrations, logos, symbols and decorations.
                                                                                                                                                                                                                                                                                                                                                                              8. Exact printed text and lettering.
                                                                                                                                                                                                                                                                                                                                                                              9. Exact stripe patterns, borders and color patterns.
                                                                                                                                                                                                                                                                                                                                                                              10. Exact placement, scale and orientation of every visible design element.
                                                                                                                                                                                                                                                                                                                                                                              11. Exact front-panel design.
                                                                                                                                                                                                                                                                                                                                                                              12. Exact proportions of the garment.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT redesign the clothing.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT invent a new print.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT replace the graphic.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT simplify the graphic.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT remove lettering.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT change the colors.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT add decorations that are not present.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT change the neckline.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT change sleeve construction.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT turn the garment into another style.

                                                                                                                                                                                                                                                                                                                                                                              DO NOT substitute a similar-looking garment.

                                                                                                                                                                                                                                                                                                                                                                              If the reference image contains a front view of the garment, treat that front view as the authoritative reference for the front of the garment.

                                                                                                                                                                                                                                                                                                                                                                              If the reference contains multiple views, use them only to understand the same garment and its construction. Do not combine unrelated designs from different views.

                                                                                                                                                                                                                                                                                                                                                                              The final image should look like a real high-end fashion campaign photograph of a model actually wearing THE SAME GARMENT shown in the uploaded reference.

                                                                                                                                                                                                                                                                                                                                                                              Make the garment naturally fit the model's body while preserving its original construction and design.

                                                                                                                                                                                                                                                                                                                                                                              Maintain sharp, clean and readable garment artwork.

                                                                                                                                                                                                                                                                                                                                                                              The uploaded clothing image is the source of truth for the garment.
                                                                                                                                                                                                                                                                                                                                                                              Photorealistic result.
                                                                                                                                                                                                                                                                                                                                                                              High garment detail.
                                                                                                                                                                                                                                                                                                                                                                              Professional fashion photography.
                                                                                                                                                                                                                                                                                                                                                                              Natural fabric folds and realistic clothing physics.
                                                                                                                                                                                                                                                                                                                                                                              Accurate garment construction.
                                                                                                                                                                                                                                                                                                                                                                              No redesign.
                                                                                                                                                                                                                                                                                                                                                                              No reinterpretation.
                                                                                                                                                                                                                                                                                                                                                                              No replacement clothing.
                                                                                                                                                                                                                                                                                                                                                                              `;

                                                                                                                                                                                                                                                                                                                                                                                  // Create multipart form data for OpenAI
                                                                                                                                                                                                                                                                                                                                                                                      const openaiForm = new FormData();

                                                                                                                                                                                                                                                                                                                                                                                          openaiForm.append(
                                                                                                                                                                                                                                                                                                                                                                                                "model",
                                                                                                                                                                                                                                                                                                                                                                                                      "gpt-image-1.5"
                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                              openaiForm.append(
                                                                                                                                                                                                                                                                                                                                                                                                                    "prompt",
                                                                                                                                                                                                                                                                                                                                                                                                                          prompt
                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                  openaiForm.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                        "input_fidelity",
                                                                                                                                                                                                                                                                                                                                                                                                                                              "high"
                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                      openaiForm.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                            "quality",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "high"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          openaiForm.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "size",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "1024x1024"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              openaiForm.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "output_format",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "png"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  openaiForm.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "image",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              new Blob([imageBuffer], {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type: mimeType
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  originalName
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Send image edit request to OpenAI
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const response = await fetch(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "https://api.openai.com/v1/images/edits",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Authorization: `Bearer ${OPENAI_API_KEY}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    body: openaiForm
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Read response
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const responseText = await response.text();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          let result;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    result = JSON.parse(responseText);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (parseError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "OpenAI returned invalid JSON:",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              responseText
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return res.status(502).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  error: "OpenAI returned an invalid response."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Handle OpenAI error
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!response.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "OpenAI API error:",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          result
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const message =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              result &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      result.error &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              result.error.message
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? result.error.message
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : "OpenAI image generation failed.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return res.status(response.status).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                error: message
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Make sure an image was returned
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        !result.data ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              !result.data[0] ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    !result.data[0].b64_json
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "No image returned:",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              result
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return res.status(502).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  error: "OpenAI did not return an image."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Convert base64 image into a browser-friendly data URL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const imageData =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          `data:image/png;base64,${result.data[0].b64_json}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Return image to OBITREND frontend
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return res.status(200).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              image: imageData
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "OBITREND generate error:",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    error
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return res.status(500).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  error:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          error && error.message
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? error.message
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : "Something went wrong while generating the fashion image."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };